package com.rodrigosambade.offlinefirst; import android.content.Context;import androidx.annotation.NonNull;import androidx.work.*;public class SyncWorker extends Worker{public SyncWorker(@NonNull Context c,@NonNull WorkerParameters p){super(c,p);}@NonNull @Override public Result doWork(){NoteDao dao=AppDatabase.get(getApplicationContext()).notes();for(NoteEntity n:dao.pending()){try{Thread.sleep(80);}catch(InterruptedException e){Thread.currentThread().interrupt();return Result.retry();}dao.markSynced(n.id);}return Result.success();}}